    }

    [data-theme="dark"],
    @media (prefers-color-scheme: dark) {
      :root {
        --shelf-chip-bgColor-bar: transparent;
        --shelf-chip-bgColor-idle: var(--shelf-bgColor-surface, #1f2937);
        --shelf-chip-bgColor-hover: var(--shelf-bgColor-surface-hover, #374151);
