        --shelf-chip-fgColor-pressed: var(--shelf-fgColor-onAccent, #ffffff);
        --shelf-chip-borderColor-idle: var(--shelf-borderColor-default, #4b5563);
        --shelf-chip-borderColor-hover: var(--shelf-borderColor-strong, #6b7280);
        --shelf-chip-borderColor-pressed: var(--shelf-borderColor-accent, #2563eb);
      }
    }

    .chip-filter {
      display: flex;
      gap: var(--shelf-chip-gap);
      padding: var(--shelf-chip-bar-padding);
      background-color: var(--shelf-chip-bgColor-bar);
    }

    .chip-button {
      appearance: none;
      background-color: var(--shelf-chip-bgColor-idle);
      color: var(--shelf-chip-fgColor-idle);
      border: 1px solid var(--shelf-chip-borderColor-idle);
      border-radius: var(--shelf-chip-border-radius);
      padding: var(--shelf-chip-padding-block) var(--shelf-chip-padding-inline);
      cursor: pointer;
      font: inherit;
      transition-property: background-color, color, border-color;
      transition-duration: var(--shelf-motion-duration-fast);
      transition-timing-function: var(--shelf-motion-easing-standard);
    }

    .chip-button[aria-pressed="true"] {
      background-color: var(--shelf-chip-bgColor-pressed);
      color: var(--shelf-chip-fgColor-pressed);
      border-color: var(--shelf-chip-borderColor-pressed);
    }

    .chip-button:hover:not([aria-pressed="true"]) {
      background-color: var(--shelf-chip-bgColor-hover);
      color: var(--shelf-chip-fgColor-hover);
      border-color: var(--shelf-chip-borderColor-hover);
    }
  }
`;

export function ChipFilter(): JSX.Element {
  const [active, setActive] = useState<ChipLabel>('All');

  return (
    <>
      <style>{CHIP_STYLES}</style>
      <div className="chip-filter" role="group" aria-label="Filter chips">
        {CHIPS.map((label) => (
          <button
            key={label}
            type="button"
            className="chip-button"
            aria-pressed={active === label}
            onClick={() => setActive(label)}
          >
            {label}
          </button>
        ))}
      </div>
    </>
  );
}
